/// <summary>
/// SalesOrderLineCDSV2Entity COC class
/// </summary>
[ExtensionOf(tableStr(SalesOrderLineCDSV2Entity))]
final class METSalesOrderLineCDSV2Entity_Extension
{
    #OCCRetryCount

}

Method.Source:
    /// <summary>
    /// CoC method for InsertEntityDataSource method
    /// </summary>
    /// <param name = "_entityCtx">Param of type DataEntityRuntimeContext</param>
    /// <param name = "_dataSourceCtx">Param of type DataEntityDataSourceRuntimeContext</param>
    /// <returns>true of false</returns>
    public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        SalesLine                       metSalesLineStd;
        SalesTable                      metSalesTableStd;        
        METSalesLine                    metSalesLine;
        InventDim                       metInventDimStd;
        boolean                         modified;

        if (_dataSourceCtx.name() == dataentitydatasourcestr(SalesOrderLineCDSV2Entity, SalesOrderLineEntity) &&
            _entityCtx.isDatabaseOperationInsert())
        {
            SalesOrderLineV2Entity salesorderLineEntity = _dataSourceCtx.getBuffer();
            metSalesTableStd  = SalesTable::find(salesorderLineEntity.SalesOrderNumber);

            if (metSalesTableStd.Reservation == ItemReservation::Automatic && metSalesTableStd.metSubstitutionActive())
            {
                metInventDimStd.InventSiteId        = salesorderLineEntity.ShippingSiteId;
                metInventDimStd.InventLocationId    = salesorderLineEntity.ShippingWarehouseId;
                metInventDimStd   = InventDim::findOrCreate(metInventDimStd);

                InventQty   inventQty = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(salesorderLineEntity.ItemNumber,
                                                                                              metInventDimStd.inventDimId,
                                                                                              salesorderLineEntity.OrderedSalesQuantity,
                                                                                              salesorderLineEntity.SalesUnitSymbol,
                                                                                              InventTable::find(salesorderLineEntity.ItemNumber).inventUnitId(),
                                                                                              NoYes::Yes);

                inventQty = decRound(inventQty,InventTable::inventDecimals(salesorderLineEntity.ItemNumber));

                METSalesItemSubstitution metSalesItemSubstitution = METSalesItemSubstitution::construct();

                boolean found    = metSalesItemSubstitution.findSubstitutionItem(salesorderLineEntity.ItemNumber, 
                                                                                 metInventDimStd,
                                                                                 metSalesTableStd.CustAccount,
                                                                                 metSalesTableStd.custTable_CustAccount().CustGroup,
                                                                                 inventQty);
                metSalesLine    = metSalesItemSubstitution.parmMetSalesLine();                    

                if (found && metSalesLine.SubstituteReplacementItemID != '' && 
                    salesorderLineEntity.ItemNumber != metSalesLine.SubstituteReplacementItemID)
                {
                    UnitOfMeasureSymbol salesUnit   = metSalesItemSubstitution.substitutionItemSalesUnit(metSalesLine.SubstituteReplacementItemID, metSalesTableStd.InventSiteId);
                    SalesQty    salesQty    = metSalesItemSubstitution.substitutionItemSalesQty(salesorderLineEntity.ItemNumber,
                                                                                                metSalesLine.SubstituteReplacementItemID,
                                                                                                metSalesTableStd.InventSiteId,
                                                                                                salesUnit,
                                                                                                salesorderLineEntity.OrderedSalesQuantity,
                                                                                                metSalesItemSubstitution.parmRounding());

                    salesorderLineEntity.ItemNumber             = metSalesLine.SubstituteReplacementItemID;
                    salesorderLineEntity.OrderedSalesQuantity   = salesQty;
                    salesorderLineEntity.SalesUnitSymbol        = salesUnit;

                    salesorderLineEntity.METSubstituteOriginalItemID        = metSalesLine.SubstituteOriginalItemID;
                    salesorderLineEntity.METSubstituteReplacementItemID     = metSalesLine.SubstituteReplacementItemID;
                    salesorderLineEntity.METSubstituteParentItemID          = metSalesLine.SubstituteParentItemID;
                    salesorderLineEntity.METSubstitutionType                = metSalesLine.SubstitutionType;
                    salesorderLineEntity.METSubstitutionCode                = metSalesLine.SubstitutionCode;
                    salesorderLineEntity.METSubstitutionSetupRefRecID       = metSalesLine.SubstitutionSetupRefRecID; 
                    salesorderLineEntity.METOrderExtractStatus              = METOrderExtractStatus::None;
                    modified = true;

                    _dataSourceCtx.setBuffer(salesorderLineEntity);
                }
            }            
        }

        boolean ret = next insertEntityDataSource(_entityCtx, _dataSourceCtx);        

        if (_dataSourceCtx.name() == dataentitydatasourcestr(SalesOrderLineCDSV2Entity, SalesOrderLineEntity))
        {
            
            SalesOrderLineV2Entity  salesorderLineEntity = _dataSourceCtx.getBuffer();   
            METSalesLine            METSalesLineUpdate;

            select firstonly metSalesLineStd
                where metSalesLineStd.InventTransId == salesorderLineEntity.InventoryLotId
                outer join METSalesLineUpdate
                where METSalesLineUpdate.SalesLine  == metSalesLineStd.RecId;

            if(modified)
            {
                if (METSalesLineUpdate.RecId)
                {
                    ttsbegin;

                    METSalesLineUpdate.selectForUpdate(true);
                    metSalesLineUpdate.OrderExtractStatus   = METOrderExtractStatus::Open;                
                    metSalesLineUpdate.update();

                    ttscommit;
                }   
            }
            if(ReasonTable::find(METSalesLineUpdate.ReasonId).METCancelLineOnCreation)
            {
                metSalesLineStd.selectForUpdate(true);
                SalesUpdateRemain::updateDeliveryRemainder(metSalesLineStd, 0, 0);
            }
       
        }
    
        return ret;
    }

    /// <summary>
    /// Map data fields to virtual fields
    /// </summary>
    public void postLoad()
    {
        next postLoad();

        this.METReservedQuantity = SalesLine::findInventTransId(this.InventoryLotId).reservedPhysical();

    }
